#pragma scop
{
  const int TS_I = 32;
  const int TS_J = 32;
  const int TS_K = 32;
  int ii, jj, kk;
  int i, j, k;
  int i_max, j_tile_max, j_start, j_end, k_end;
  DATA_TYPE bik, aik;

  #pragma omp parallel for shared(C,A,B,alpha,beta) schedule(dynamic)
  for (ii = 0; ii < _PB_N; ii += TS_I) {
    i_max = (ii + TS_I < _PB_N) ? ii + TS_I : _PB_N;
    j_tile_max = ii + TS_I - 1;

    for (i = ii; i < i_max; i++) {
      #pragma omp simd
      for (j = 0; j <= i; j++)
        C[i][j] *= beta;
    }

    for (jj = 0; jj <= j_tile_max; jj += TS_J) {
      for (kk = 0; kk < _PB_M; kk += TS_K) {
        k_end = (kk + TS_K < _PB_M) ? kk + TS_K : _PB_M;
        for (i = ii; i < i_max; i++) {
          j_start = jj;
          j_end = (jj + TS_J < i + 1) ? jj + TS_J : i + 1;
          if (j_start >= j_end) continue;

          for (k = kk; k < k_end; k++) {
            bik = B[i][k];
            aik = A[i][k];
            for (j = j_start; j < j_end; j++) {
              C[i][j] += A[j][k] * alpha * bik
                       + B[j][k] * alpha * aik;
            }
          }
        }
      }
    }
  }
}
#pragma endscop

